const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const whiteIsland = ee.Geometry.Point([177.18, -37.52]);  // Note: [lon, lat]
  const region = whiteIsland.buffer(20000);  // 20km buffer for plume detection

  // Target date: January 7, 2025 (future date - may not have data)
  const targetDate = '2025-01-07';
  const startDate = ee.Date(targetDate).advance(-1, 'day');  // ±1 day window
  const endDate = ee.Date(targetDate).advance(1, 'day');

  // Function to mask clouds in Sentinel-2
  function maskS2Clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Function to detect plume (bright, reflective features in visible bands)
  function detectPlume(image) {
    // Use visible bands: blue (B2), green (B3), red (B4)
    const visible = image.select(['B2', 'B3', 'B4']);
    const brightness = visible.reduce(ee.Reducer.mean()).gt(0.25);  // High reflectance threshold

    // Mask out water (NDWI > 0) and vegetation (NDVI > 0.3)
    const ndwi = image.normalizedDifference(['B3', 'B8']).rename('NDWI');
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    const notWater = ndwi.lt(0.1);  // Not water
    const notVeg = ndvi.lt(0.3);    // Not vegetation

    // Plume mask: bright, not water, not vegetation
    return brightness.and(notWater).and(notVeg);
  }

  // 2. Data Acquisition & Check
  let img = null;
  let collectionName = '';

  // Try Sentinel-2 first (10m resolution, good for visible plume)
  let s2Col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(region)
    .filterDate(startDate, endDate)
    .map(maskS2Clouds);

  let s2Size = s2Col.size().getInfo();
  console.log(`Sentinel-2 images (${targetDate} ±1 day): ${s2Size}`);

  if (s2Size > 0) {
    img = s2Col.median().clip(region);
    collectionName = 'Sentinel-2';
  } else {
    // Try Landsat 8
    let ls8Col = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(region)
      .filterDate(startDate, endDate);

    let ls8Size = ls8Col.size().getInfo();
    console.log(`Landsat 8 images (${targetDate} ±1 day): ${ls8Size}`);

    if (ls8Size > 0) {
      // Simple cloud mask for Landsat using QA_PIXEL
      function maskL8Clouds(image) {
        const qa = image.select('QA_PIXEL');
        const cloudMask = qa.bitwiseAnd(1 << 3).eq(0)  // Cloud
                          .and(qa.bitwiseAnd(1 << 4).eq(0));  // Cloud shadow
        return image.updateMask(cloudMask);
      }

      img = ls8Col.map(maskL8Clouds).median().clip(region);
      collectionName = 'Landsat 8';
    } else {
      // Try MODIS (daily, but lower resolution)
      let modisCol = ee.ImageCollection('MODIS/061/MOD09GA')
        .filterBounds(region)
        .filterDate(startDate, endDate);

      let modisSize = modisCol.size().getInfo();
      console.log(`MODIS images (${targetDate} ±1 day): ${modisSize}`);

      if (modisSize > 0) {
        img = modisCol.median().clip(region);
        collectionName = 'MODIS';
      } else {
        console.log(`<answer>C1</answer>`);
        return;
      }
    }
  }

  console.log(`Using ${collectionName} image`);

  // 3. Processing - Detect plume and count pixels
  let plumeMask;
  if (collectionName === 'Sentinel-2') {
    plumeMask = detectPlume(img);
  } else if (collectionName === 'Landsat 8') {
    // For Landsat 8, adjust band names: SR_B2 (blue), SR_B3 (green), SR_B4 (red)
    // Create a simple brightness mask
    const visible = img.select(['SR_B2', 'SR_B3', 'SR_B4']);
    const brightness = visible.reduce(ee.Reducer.mean()).gt(0.25);
    plumeMask = brightness;
  } else if (collectionName === 'MODIS') {
    // MODIS: surface reflectance bands 1-7
    const brightness = img.select('sur_refl_b01').gt(0.25);  // Band 1 (red)
    plumeMask = brightness;
  }

  // Count plume pixels
  const plumeCount = plumeMask.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 1000,  // Use 1km scale for efficiency
    maxPixels: 1e9
  }).get('constant').getInfo();

  console.log(`Plume pixels detected: ${plumeCount}`);

  // 4. Check for valid pixels
  if (plumeCount === 0 || plumeCount === null) {
    console.log(`<answer>C2</answer>`);
    return;
  }

  // 5. Calculate plume direction
  // Get mean latitude of plume pixels
  const plumeLat = plumeMask.multiply(ee.Image.pixelLonLat().select('latitude'))
    .reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    }).get('constant').getInfo();

  const ventLat = -37.52;  // White Island latitude

  console.log(`Vent latitude: ${ventLat}`);
  console.log(`Mean plume latitude: ${plumeLat}`);

  // 6. Validation & Final Answer
  if (plumeLat === null || plumeLat === undefined || Math.abs(plumeLat) > 90) {
    console.log(`<answer>C3</answer>`);
    return;
  }

  // If plume mean latitude is SOUTH of vent (more negative in Southern Hemisphere)
  const isSouth = plumeLat < ventLat;
  console.log(`Plume travels south: ${isSouth}`);

  // Threshold: at least 0.01 degree difference (approx 1.1 km)
  if (isSouth && Math.abs(plumeLat - ventLat) > 0.01) {
    console.log(`<answer>A</answer>`);
  } else {
    console.log(`<answer>B</answer>`);
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
